CREATE   PROCEDURE [synapse_ce].[usp_Update_apuk_panel]
AS
BEGIN
	UPDATE tgt SET 
		tgt.[apuk_assessmentevent] = stg.[apuk_assessmentevent],
		tgt.[apuk_assessmentevent_entitytype] = stg.[apuk_assessmentevent_entitytype],
		tgt.[apuk_assessmenteventname] = stg.[apuk_assessmenteventname],
		tgt.[apuk_assessmentvenue] = stg.[apuk_assessmentvenue],
		tgt.[apuk_assessmentvenue_entitytype] = stg.[apuk_assessmentvenue_entitytype],
		tgt.[apuk_assessmentvenuename] = stg.[apuk_assessmentvenuename],
		tgt.[apuk_date] = stg.[apuk_date],
		tgt.[apuk_name] = stg.[apuk_name],
		tgt.[apuk_panelid] = stg.[apuk_panelid],
		tgt.[apuk_paneltype] = stg.[apuk_paneltype],
		tgt.[apuk_tribunalchair] = stg.[apuk_tribunalchair],
		tgt.[apuk_tribunalchair_entitytype] = stg.[apuk_tribunalchair_entitytype],
		tgt.[apuk_tribunalchairname] = stg.[apuk_tribunalchairname],
		tgt.[apuk_tribunalchairyominame] = stg.[apuk_tribunalchairyominame],
		tgt.[apuk_tribunallaymember] = stg.[apuk_tribunallaymember],
		tgt.[apuk_tribunallaymember_entitytype] = stg.[apuk_tribunallaymember_entitytype],
		tgt.[apuk_tribunallaymembername] = stg.[apuk_tribunallaymembername],
		tgt.[apuk_tribunallaymemberyominame] = stg.[apuk_tribunallaymemberyominame],
